"""Publish exact-version repair evidence, floor diagrams and model downloads."""
import json,hashlib,math,html
from pathlib import Path
from street_city_shop_street import inventory,ROOT
OUT=ROOT/'output/street-social-city-production/interior-repair-v1';result=json.loads((OUT/'acceptance.json').read_text('utf-8'));assert result['status']=='passed' and result['remaining_findings']==0
audit=json.loads((OUT/'fixtures-expanded-after.json').read_text('utf-8'));by_id={r['building']:r for r in audit['buildings']};assert len(by_id)==96
changes=[];data=[];files=[]
def yaw(item):return item.get('yaw_deg',math.degrees(item.get('yaw_rad',0)))
for b in inventory():
 bid=b['building'];folder=OUT.parent/f'{bid}-modular-components-v1/assembly-building';report=json.loads((folder/'assembly-report.json').read_text('utf-8'));before=json.loads((OUT/'before'/bid/'assembly-report.json').read_text('utf-8'));old={i['name']:i for i in before['instances']};model=folder/f'{bid}-complete-2k.glb';assert hashlib.sha256(model.read_bytes()).hexdigest()==by_id[bid]['source_sha256']
 acceptance=json.loads((folder/'acceptance.json').read_text('utf-8'));assert acceptance['status']=='passed' and acceptance['sha256']==by_id[bid]['source_sha256']
 for i in report['instances']:
  previous=old.get(i['name'])
  if not previous:continue
  moved=max(abs(a-c) for a,c in zip(i['position_m'],previous['position_m']))>.002;rotated=abs((yaw(i)-yaw(previous)+180)%360-180)>.01;geometry=report['sources'][i['asset']]['sha256']!=before['sources'][previous['asset']]['sha256']
  if (moved or rotated or geometry) and i['asset'] in ['sink','handwash','double-sink','wardrobe','toilet','fridge','bed']:changes.append(dict(building=bid,name=i['name'],asset=i['asset'],old_position_m=previous['position_m'],position_m=i['position_m'],old_yaw_deg=yaw(previous),yaw_deg=yaw(i),pose_changed=moved or rotated,source_changed=geometry))
 name=b.get('small_shop_design',{}).get('name',{'S18':'日式民宿','S19':'溫泉會館'}.get(bid,bid));data.append(dict(id=bid,name=name,width=b['footprint_m'][0],depth=b['footprint_m'][1],triangles=acceptance['floor_triangles']))
 for no in [1,2,3]:
  svg=OUT/f'floor-plans/{bid}-F{no:02d}.svg';assert by_id[bid]['source_sha256'] in svg.read_text('utf-8');files.append(svg)
 files.append(model)
stats={name:sum(i['asset'] in ids and (i['pose_changed'] or name=='wardrobes') for i in changes) for name,ids in [('basins',['sink','handwash','double-sink']),('wardrobes',['wardrobe']),('toilets',['toilet']),('fridges',['fridge']),('beds',['bed'])]}
(OUT/'changes.json').write_text(json.dumps(dict(stats=stats,changes=changes),ensure_ascii=False,indent=2),'utf-8')
embedded=json.dumps(data,ensure_ascii=False).replace('<','\\u003c');cards=[]
for bid in ['S04','S10','S24','S30','S41','S46','S52','S58','S70','S76','S88','S94']:cards.append(f'<a href="floor-plans/{bid}-F01.svg">{bid} 一樓隔間</a>')
page='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>商店街室內修正驗收</title><style>
body{font:17px/1.7 system-ui,"Microsoft JhengHei",sans-serif;background:#f5f3ec;color:#263d37;max-width:1450px;margin:auto;padding:30px}h1{font-size:34px}a{color:#116b64}section{background:white;padding:24px;margin:24px 0;border-radius:14px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}img{max-width:100%;height:auto}.pair img{width:100%;border-radius:8px}.controls{display:flex;gap:12px;flex-wrap:wrap}button,select{padding:10px;font:inherit}#plan{width:100%;max-height:1350px;object-fit:contain;background:#faf9f4}.links{display:flex;gap:18px;flex-wrap:wrap}.note{border-left:5px solid #337e6c;padding-left:18px}@media(max-width:800px){.pair{grid-template-columns:1fr}}
</style><h1>商店街室內 · 修正與驗收</h1>'''
page+=f'<p>96 棟／288 層全部更新。補齊 18 個缺牆廚房／試衣間及牆角；修正 {stats["basins"]} 個水槽、{stats["wardrobes"]} 個衣櫃、{stats["toilets"]} 個馬桶與 {stats["fridges"]} 台冰箱的方向、尺寸或使用位置。</p><p class="note">實際 GLB、Rust 收據、2m通道、門牆連接、設備使用面及站立區已驗收。Unreal 保存後重新載入並等待物理初始化，再檢查門牆碰撞。此批仍為靜態場景；門／電梯遊戲控制器尚未接入。</p><div class="links"><a href="acceptance.json">本輪驗收</a><a href="changes.json">逐件修正紀錄</a><a href="fixtures-expanded-after.json">設備／門牆稽核</a><a href="../world-ground-v1/index.html">Unreal 完整場景</a><a href="../../../StreetSocialCity/OpenCity.cmd">啟動 Unreal</a><a href="../../../model3d.md">製作方法</a></div>'
page+=f'<p>另移動 {stats["beds"]} 張床，留出較短臥室的衣櫃使用空間。</p>'
page+='''<section><h2>洗手台前後對照</h2><div class="pair"><div><p>修正前：水龍頭朝使用者</p><img src="S01-kitchen-basin-before.png"></div><div><p>修正後：水龍頭靠背側，使用面朝室內</p><img src="S01-kitchen-basin-after.png"></div></div></section><section><h2>Unreal 試衣間前後對照</h2><div class="pair"><div><p>修正前：只有門，缺少試衣間隔牆</p><img src="S10-unreal-interior-before.png"></div><div><p>修正後：門與完整隔間連接</p><img src="S10-unreal-interior-after.png"></div></div></section><section><h2>所有店面實際樓層圖</h2><p>由驗收後 GLB 量測，外框與模型相同；包括家具位置、設備使用方向、門扇示意及 1／5／10m 比例尺。圖為模型局部座標，世界旋轉角另標註。</p><div class="controls"><button id="previous">上一棟</button><select id="building"></select><button id="next">下一棟</button><select id="floor"><option value="1">一樓</option><option value="2">二樓</option><option value="3">三樓</option></select></div><p id="metrics"></p><div class="links"><a id="svg" target="_blank">開啟 SVG</a><a id="model">整棟 GLB</a><a id="blend">整棟 Blender</a><a id="floorModel">此層 GLB</a></div><img id="plan"></section>'''
page+='<section><h2>新增局部隔間的店面</h2><div class="links">'+''.join(cards)+'</div></section><script>const records='+embedded+''';const select=document.querySelector('#building'),floor=document.querySelector('#floor');for(const r of records){select.add(new Option(r.id+' '+r.name,r.id))}function show(){const r=records.find(r=>r.id===select.value),n=Number(floor.value),name=r.id+'-F'+String(n).padStart(2,'0'),base='../'+r.id+'-modular-components-v1/assembly-building/';document.querySelector('#metrics').textContent=r.id+' '+r.name+' · '+r.width+'×'+r.depth+'m · 本層 '+Number(r.triangles[String(n)]).toLocaleString()+' 三角面';document.querySelector('#plan').src='floor-plans/'+name+'.svg';document.querySelector('#svg').href='floor-plans/'+name+'.svg';document.querySelector('#model').href=base+r.id+'-complete-2k.glb';document.querySelector('#blend').href=base+r.id+'-complete-2k.blend';document.querySelector('#floorModel').href=base+name+'-complete-2k.glb'}select.onchange=show;floor.onchange=show;document.querySelector('#previous').onclick=()=>{select.selectedIndex=(select.selectedIndex+records.length-1)%records.length;show()};document.querySelector('#next').onclick=()=>{select.selectedIndex=(select.selectedIndex+1)%records.length;show()};select.value='S10';show();</script></html>'''
for name in ['S01-kitchen-basin-before.png','S01-kitchen-basin-after.png','S10-unreal-interior-before.png','S10-unreal-interior-after.png']:assert (OUT/name).is_file();files.append(OUT/name)
(OUT/'index.html').write_text(page,'utf-8');files.extend([OUT/'index.html',OUT/'acceptance.json',OUT/'changes.json'])
(OUT/'delivery.json').write_text(json.dumps(dict(status='passed',stats=stats,files=[dict(path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),bytes=p.stat().st_size) for p in files]),indent=2),'utf-8');print('Interior repair published',stats)
